"""C0 (deterministic, no LLM) report generator: JSON valid against contracts/schemas/report.json + Markdown.

'mitigated' (service restored per the verifier) is kept strictly separate from 'root_cause_confirmed'
(only set through the verifier / experiment ground truth, never from temporal order).
"""
from __future__ import annotations

import html
import re

from backend import ENGINE_VERSION
from backend.domain.clock import Clock, iso
from backend.repositories.base import Repository

STATIC_LIMITATIONS = [
    "Deterministic C0 report: generated by rules only, no LLM involved.",
    "Confidence values are a ranking aid computed from evidence coverage, independent signal types and contradictions; they are not calibrated probabilities.",
    "'Mitigated' means the verifier saw service restored over the stability window; it does not confirm the root cause.",
    "Sandbox only; a small known topology is an easy case and results do not generalise to production.",
]


class NoDiagnosis(ValueError):
    pass


class ReportGenerator:
    def __init__(self, repo: Repository, clock: Clock) -> None:
        self.repo, self.clock = repo, clock

    def build(self, incident_id: str) -> dict:
        inc = self.repo.get_incident(incident_id)
        if inc is None:
            raise KeyError(incident_id)
        diag = self.repo.latest_diagnosis(incident_id)
        if diag is None:
            raise NoDiagnosis(incident_id)
        evidence = self.repo.list_evidence(incident_id)
        plans = self.repo.list_plans(incident_id)
        decisions = self.repo.list_decisions(incident_id)
        executions = self.repo.list_executions(incident_id)
        verifications = self.repo.list_verifications(incident_id)
        limitations = list(STATIC_LIMITATIONS)
        failed = [e for e in evidence if e.status in ("error", "timeout")]
        if failed:
            limitations.append(f"{len(failed)} evidence queries failed (error/timeout): those signals were NOT observed and are not treated as absence of a fault.")
        unverifiable = [v for v in verifications if v.verdict == "unverifiable"]
        if unverifiable:
            limitations.append("At least one verification was unverifiable (a check could not be established); recovery was not declared (fail closed).")
        mitigated = bool(verifications) and verifications[-1].verdict == "recovered" and inc.state in ("recovered", "closed")
        escalated = inc.state == "escalated" or inc.outcome == "escalated" or any(p.action_id == "escalate" for p in plans)
        report = {
            "schema_version": "1",
            "generated_at": iso(self.clock.now()),
            "generator": {"mode": "deterministic", "version": ENGINE_VERSION},
            "incident": inc.to_contract(),
            "timeline": [e.to_contract() for e in self.repo.list_events(incident_id)],
            "evidence_ids": [e.evidence_id for e in evidence],
            "diagnosis": diag.to_contract(),
            "plans": [p.to_contract() for p in plans],
            "decisions": [d.to_contract() for d in decisions],
            "executions": [x.to_contract() for x in executions],
            "verifications": [v.to_contract() for v in verifications],
            "outcome": {"mitigated": mitigated, "root_cause_confirmed": bool(inc.root_cause_confirmed), "escalated": escalated},
            "limitations": limitations,
        }
        return report

    # ------------------------------------------------------------------ markdown
    @staticmethod
    def _md(text: object) -> str:
        """Neutralise text for Markdown: escape HTML, table pipes and newlines (evidence text is untrusted)."""
        s = html.escape(str(text), quote=False)
        s = re.sub(r"[\r\n]+", " ", s)
        return s.replace("|", "\\|").replace("`", "'")

    def render_markdown(self, report: dict) -> str:
        m = self._md
        inc, diag, out = report["incident"], report["diagnosis"], report["outcome"]
        L = [f"# Incident report {inc['incident_id']}", "",
             f"Generated {report['generated_at']} by `{m(report['generator']['mode'])}` generator {m(report['generator']['version'])}.", "",
             "## Summary", "",
             f"- State: **{inc['state']}**, severity **{inc['severity']}**, opened {inc['opened_at']}" + (f", closed {inc['closed_at']}" if inc.get("closed_at") else ""),
             f"- Services: {', '.join(m(s) for s in inc['services'])}",
             f"- Symptoms: " + "; ".join(m(s) for s in inc["symptoms"]),
             f"- **Mitigated:** {'yes' if out['mitigated'] else 'no'}  |  **Root cause confirmed:** {'yes' if out['root_cause_confirmed'] else 'no'}  |  **Escalated:** {'yes' if out['escalated'] else 'no'}",
             "", "> Mitigated (service restored) is not the same as root cause confirmed.", "", "## Timeline", "",
             "| event_time | collected_at | kind | service | summary | evidence |", "|---|---|---|---|---|---|"]
        for e in report["timeline"]:
            L.append(f"| {e['event_time']} | {e['collected_at']} | {e['kind']}{' (suppressed)' if e.get('suppressed') else ''} | {m(e.get('service', ''))} | {m(e['summary'])} | {', '.join(e.get('evidence_refs', []))} |")
        L += ["", "## Diagnosis", "", f"Origin: {diag['origin']}; engine {m(diag.get('engine_version', ''))}; generated {diag['generated_at']}.", ""]
        for h in diag["hypotheses"]:
            L += [f"### {h['rank']}. {m(h['cause_id'])} - {h['status']} (confidence {h['confidence']:.2f})", "", m(h["description"]), ""]
            if h.get("confidence_basis"):
                L += ["Confidence basis:"] + [f"- {m(b)}" for b in h["confidence_basis"]] + [""]
            L += ["Supporting claims:"] + [f"- [{c['type']}] {m(c['text'])} ({', '.join(c['evidence'])})" for c in h["claims"]] + [""]
            L += ["Contradicting evidence:"] + ([f"- {m(c['text'])} ({', '.join(c['evidence'])})" for c in h["contradicting"]] or ["- none recorded"]) + [""]
            L += ["Alternatives:"] + [f"- {m(a)}" for a in h["alternatives"]] + [""]
            L += ["Unknowns:"] + ([f"- {m(u)}" for u in h["unknowns"]] or ["- none"]) + [""]
        if diag.get("recommended_action"):
            ra = diag["recommended_action"]
            L += [f"Recommended action: `{ra['action_id']}` {m(ra['params'])}", ""]
        L += ["## Remediation", ""]
        if not report["plans"]:
            L += ["No plan was created.", ""]
        for p in report["plans"]:
            L += [f"- {p['plan_id']}: `{p['action_id']}` {m(p['params'])}, risk {p['risk_class']}, hash `{p['plan_hash']}`. {m(p['rationale'])}"]
        for d in report["decisions"]:
            L += [f"- decision {d['decision_id']} for {d['plan_id']}: **{d['final']}** (L1 {d['l1']['result']} {', '.join(d['l1']['rule_ids'])}) {m('; '.join(d['reasons']))}"]
        for x in report["executions"]:
            L += [f"- execution {x['execution_id']} of {x['plan_id']}: **{x['result']}** {m(x.get('detail', ''))}"]
        L += ["", "## Verification", ""]
        if not report["verifications"]:
            L += ["No verification was run.", ""]
        for v in report["verifications"]:
            L += [f"### {v['execution_id']}: **{v['verdict']}** (window {v['window_start']} - {v['window_end']})", "", "| check | passed | baseline | pre-action | post-action | detail |", "|---|---|---|---|---|---|"]
            for c in v["checks"]:
                L.append(f"| {c['name']} | {'unknown (null)' if c['passed'] is None else c['passed']} | {c.get('baseline', '')} | {c.get('pre_action', '')} | {c.get('post_action', '')} | {m(c.get('detail', ''))} |")
            L.append("")
        L += ["## Evidence", "", f"{len(report['evidence_ids'])} evidence records ({report['evidence_ids'][0] if report['evidence_ids'] else '-'} .. {report['evidence_ids'][-1] if report['evidence_ids'] else '-'}). Log text inside evidence is untrusted and is not reproduced here.", "",
              "## Limitations", ""] + [f"- {m(x)}" for x in report["limitations"]]
        return "\n".join(L) + "\n"
